package com.gymmind.nutrition.domain.model;
import com.gymmind.shared.persistence.TenantScopedEntity; import jakarta.persistence.*;
@Entity @Table(name="nutrition_food") public class NutritionFood extends TenantScopedEntity { @Column(nullable=false,length=128) String name; @Column(nullable=false) double calories; @Column(nullable=false) double protein; @Column(nullable=false) double carbohydrate; @Column(nullable=false) double fat; @Column(name="serving_size",nullable=false,length=64) String servingSize; protected NutritionFood(){} private NutritionFood(Long t,String n,double c,double p,double carb,double f,String s){super(t);if(n==null||n.isBlank()||c<0||p<0||carb<0||f<0||s==null||s.isBlank())throw new IllegalArgumentException("Invalid food");name=n.trim();calories=c;protein=p;carbohydrate=carb;fat=f;servingSize=s.trim();} public static NutritionFood create(Long t,String n,double c,double p,double carb,double f,String s){return new NutritionFood(t,n,c,p,carb,f,s);} public String getName(){return name;} public double getCalories(){return calories;} public double getProtein(){return protein;} public double getCarbohydrate(){return carbohydrate;} public double getFat(){return fat;} public String getServingSize(){return servingSize;} }
